"""Authenticated JSON endpoints, including services generated by Creator."""

from .transport import Request


def validate(service):
    if service.settlement != "api_key":
        raise ValueError("HTTP adapters require API-key settlement")


async def prepare(service, payload, key, http, timeout):
    return Request(service.url, json=payload, headers={"Authorization": f"Bearer {key}"})


def parse(service, payload, response, data, context):
    return data, {"method": "api_key", "status": "success"}, None
